  return require_index();
})();


// Adapter: intake-plain-notice
//
// The two notices no model touches: the confirmation for a complete submission, and the neutral
// acknowledgement for one a reviewer has to look at.
//
// Neither carries an Article 50 marking, and that is the point, not an omission. A
// supplier who sees the marking on a gap notice and not on a confirmation has learned something
// true about which of the two a model wrote.
//
// Node settings: JavaScript, Run Once for All Items.

const verdict = $('Assess verdict').first().json;

const notice =
  verdict.verdict === 'conform'
    ? PPWR_INTAKE.confirmation({ context: verdict._context, disclaimer: verdict.summary.disclaimer })
    : PPWR_INTAKE.underReview({ context: verdict._context, disclaimer: verdict.summary.disclaimer });

return [{ json: Object.assign({ _context: verdict._context }, notice) }];

// ppwr - the decision was recorded, the notice was not sent
//
// Not an error. Notices are off until an operator turns them on, and an item with no contact
// address is a data problem for the campaign owner rather than a failed review.

return $input.all().map((item) => ({
  json: {
    sent: false,
    subject: item.json.subject,
    body: item.json.body,
    ai_generated: item.json.ai_generated || null,
  },
}));
